1	//! i8-quantized vector segments with exact brute-force KNN.
2	//!
3	//! Same publish discipline as the text shards (magic/version header,
4	//! tmp + fsync + rename, immutable segments). At corpus scale (≤ a few
5	//! million chunks) an exact scan with metadata pre-filtering beats an ANN
6	//! graph: no recall loss, trivial filtering, no extra dependency.
7	//!
8	//! Layout (little-endian):
9	//! ```text
10	//! header (fixed 96 bytes):
11	//!   magic  b"GPXVECS1"                8
12	//!   version u32                       4
13	//!   dim u32                           4
14	//!   count u64                         8
15	//!   model_id [u8; 64] (zero-padded)  64
16	//!   reserved 8
17	//! rows (count × (16 + dim)):
18	//!   chunk_id u64 | scale f32 | reserved u32 | i8[dim]
19	//! ```
20	
21	use std::fs::{self, File, OpenOptions};
22	use std::io::{BufWriter, Write};
23	use std::path::{Path, PathBuf};
24	
25	use memmap2::Mmap;
26	use serde::{Deserialize, Serialize};
27	
28	pub const MAGIC: &[u8; 8] = b"GPXVECS1";
29	pub const VERSION: u32 = 1;
30	const HEADER_LEN: usize = 96;
31	
32	#[derive(Debug, Default, Serialize, Deserialize)]
33	pub struct VectorMeta {
34	    pub model_id: String,
35	    /// `crate::embed::embedder_revision` of the model when the vectors were
36	    /// written: the same model id can embed differently across library
37	    /// releases, and vectors of two revisions must not be mixed. Absent in
38	    /// stores written before it existed, which reads as revision 0.
39	    #[serde(default)]
40	    pub revision: u32,
41	    pub dim: usize,
42	    pub segments: Vec<String>,
43	    /// Highest chunk_id stored, for append bookkeeping.
44	    pub last_chunk_id: i64,
45	}
46	
47	pub struct VectorStore {
48	    dir: PathBuf,
49	    pub meta: VectorMeta,
50	}
51	
52	pub struct OpenSegment {
53	    mmap: Mmap,
54	    dim: usize,
55	    count: usize,
56	}
57	
58	impl VectorStore {
59	    pub fn open(dir: &Path) -> Result<Self, String> {
60	        fs::create_dir_all(dir).map_err(|e| format!("vectors dir: {e}"))?;
61	        let meta_path = dir.join("meta.json");
62	        let meta = match fs::read(&meta_path) {
63	            Ok(bytes) => {
64	                serde_json::from_slice(&bytes).map_err(|e| format!("corrupt vector meta: {e}"))?
65	            }
66	            Err(_) => VectorMeta::default(),
67	        };
68	        Ok(Self {
69	            dir: dir.to_path_buf(),
70	            meta,
71	        })
72	    }
73	
74	    /// Refuse to serve or extend a store built with a different model.
75	    pub fn check_model(&self, model_id: &str, dim: usize) -> Result<(), String> {
76	        if self.meta.model_id.is_empty() {
77	            return Ok(());
78	        }
79	        if self.meta.model_id != model_id || self.meta.dim != dim {
80	            return Err(format!(
81	                "vector store was built with model '{}' ({}d) but the active model is '{}' ({}d) — run `pixel recall embed --rebuild`",
82	                self.meta.model_id, self.meta.dim, model_id, dim
83	            ));
84	        }
85	        Ok(())
86	    }
87	
88	    /// True when the stored vectors were written by an older (or newer)
89	    /// revision of the model the store is built with: they no longer match
90	    /// what the model embeds today, so the store must be re-embedded.
91	    pub fn stale_revision(&self) -> bool {
92	        !self.meta.model_id.is_empty()
93	            && self.meta.revision != crate::embed::embedder_revision(&self.meta.model_id)
94	    }
95	
96	    /// Drop every segment but keep the model, now at its current revision:
97	    /// the store stays bound to the model it was built with while the
98	    /// corpus is embedded again.
99	    pub fn reset_for_reembed(&mut self) -> Result<(), String> {
100	        for seg in &self.meta.segments {
101	            let _ = fs::remove_file(self.dir.join(seg));
102	        }
103	        self.meta.segments.clear();
104	        self.meta.last_chunk_id = 0;
105	        self.meta.revision = crate::embed::embedder_revision(&self.meta.model_id);
106	        self.write_meta()
107	    }
108	
109	    fn write_meta(&self) -> Result<(), String> {
110	        let tmp = self.dir.join("meta.json.tmp");
111	        fs::write(&tmp, serde_json::to_vec_pretty(&self.meta).unwrap())
112	            .map_err(|e| e.to_string())?;
113	        fs::rename(&tmp, self.dir.join("meta.json")).map_err(|e| e.to_string())
114	    }
115	
116	    /// Write one immutable segment of (chunk_id, f32 vector) rows.
117	    pub fn append_segment(
118	        &mut self,
119	        model_id: &str,
120	        dim: usize,
121	        rows: &[(i64, Vec<f32>)],
122	    ) -> Result<(), String> {
123	        if rows.is_empty() {
124	            return Ok(());
125	        }
126	        self.check_model(model_id, dim)?;
127	        let seq = self.meta.segments.len() as u64 + 1;
128	        let name = format!("seg-{seq:06}.vec");
129	        let tmp = self.dir.join(format!("{name}.tmp"));
130	        {
131	            let file = OpenOptions::new()
132	                .write(true)
